def preserve_department_roles(apps, schema_editor):
    Department = apps.get_model("ministerios", "Department")
    DepartmentMembership = apps.get_model("ministerios", "DepartmentMembership")

    for department in Department.objects.all().iterator():
        memberships = []
        included_member_ids = set()
        for member in department.members.all():
            role = (
                "leader"
                if member.pk == department.leader_id
                else "participant"
            )
            memberships.append(
                DepartmentMembership(
                    department_id=department.pk,
                    member_id=member.pk,
                    role=role,
                )
            )
            included_member_ids.add(member.pk)

        if department.leader_id and department.leader_id not in included_member_ids:
            memberships.append(
                DepartmentMembership(
                    department_id=department.pk,
                    member_id=department.leader_id,
                    role="leader",
                )
            )
        DepartmentMembership.objects.bulk_create(memberships)


